fn parse_render_env(env_json: &str) -> Result<crate::bridge::RenderEnv, JsValue> {
    let value: Value = serde_json::from_str(env_json).map_err(js_err)?;
    let mut env = crate::bridge::RenderEnv::default();
    if let Some(Value::Array(ids)) = value.get("tocStyleIds") {
        env.toc_style_ids
            .extend(ids.iter().filter_map(Value::as_str).map(str::to_owned));
    }
    if let Some(Value::Object(colors)) = value.get("themeColors") {
        for (key, entry) in colors {
            if let Some(hex) = entry.as_str() {
                env.theme_colors.insert(key.clone(), hex.to_owned());
            }
        }
    }
    env.default_tab_stop_twips = value.get("defaultTabStopTwips").and_then(Value::as_f64);
    env.page_content_height = value.get("pageContentHeight").and_then(Value::as_f64);
    env.default_paragraph_style_id = value
        .get("defaultParagraphStyleId")
        .and_then(Value::as_str)
        .filter(|style| !style.is_empty())
        .map(str::to_owned);
    env.show_hidden_text = value
        .get("showHiddenText")
        .and_then(Value::as_bool)
        .unwrap_or(false);
    env.show_table_gridlines = value
        .get("showTableGridlines")
        .and_then(Value::as_bool)
        .unwrap_or(false);
    env.media_tokens = value
        .get("mediaTokens")
        .and_then(Value::as_bool)
        .unwrap_or(false);
    if let Some(Value::Object(ids)) = value.get("numericIds") {
        for (key, entry) in ids {
            if let Some(id) = entry.as_f64() {
                env.numeric_ids.insert(key.clone(), id);
            }
        }
    }
    if let Some(preview) = value.get("revisionPreview") {
        env.revision_preview = crate::bridge::RenderEnv::parse_revision_preview(preview);
    }
    Ok(env)
}

/// Document-level values lowering cannot read off a story. Every field
/// defaults, so an empty env lowers a story with built-in fallbacks.
#[derive(Clone, Debug, Default, PartialEq, serde::Deserialize, serde::Serialize)]
#[serde(default, rename_all = "camelCase")]
pub struct RenderEnv {
    pub compatibility_flags: docx_parse::CompatibilityFlags,
    #[serde(skip_serializing_if = "BTreeSet::is_empty")]
    pub toc_style_ids: BTreeSet<String>,
    /// Six-digit RGB values keyed by OOXML theme slot. A missing slot falls
    /// back to the default Office palette.
    pub theme_colors: BTreeMap<String, String>,
    /// Interval between implicit tab stops, passed through to each paragraph.
    /// `None` leaves the layout engine's own default in effect.
    pub default_tab_stop_twips: Option<f64>,
    /// Usable page height in px. Images taller than this are scaled down to
    /// fit; `None` or a non-positive value clamps nothing.
    pub page_content_height: Option<f64>,
    /// Maps a yrs `{client}:{counter}` revision or comment id to the number
    /// the layout contract carries. An unmapped id is hashed into the
    /// safe-integer range instead, which is stable but not shared with a peer
    /// that numbers the same document differently.
    pub numeric_ids: BTreeMap<String, f64>,
    /// Include hidden text in visible layout without changing the document.
    pub show_hidden_text: bool,
    /// Report borderless table cell edges as view-only guides.
    #[serde(skip_serializing_if = "std::ops::Not::not")]
    pub show_table_gridlines: bool,
    /// Revision id, as [`crate::ChangeInfo`] reports it, to the decision
    /// shown in place of its markup. A decided insertion or deletion renders
    /// as plain text or not at all, at its original positions; any other
    /// revision renders as a tracked change. Entries with other values are
    /// ignored.
    #[serde(
        skip_serializing_if = "BTreeMap::is_empty",
        deserialize_with = "deserialize_revision_preview"
    )]
    pub revision_preview: BTreeMap<String, RevisionPreview>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub paragraph_spacing_line_px: Option<f64>,
    /// Section document-grid snap pitch in px (`w:docGrid w:linePitch`),
    /// gated to an activating grid type. Lowering stamps it onto every
    /// paragraph; the engine's per-section resolve pass corrects later
    /// sections. `None` disables snapping.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub doc_grid_pitch_px: Option<f64>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub default_paragraph_style_id: Option<String>,
    /// Lower the `data:` image sources seeding wrote as the `media:{n}`
    /// tokens of their parts, which the host then resolves.
    #[serde(skip_serializing_if = "std::ops::Not::not")]
    pub media_tokens: bool,
    /// The seeded media [`Self::media_tokens`] reads; lowering takes the
    /// document's when empty.
    #[serde(skip)]
    pub media: crate::media::MediaSources,
    /// View-only layout space and hidden ranges, by host key. Never saved.
    #[serde(skip_serializing_if = "Reservations::is_empty")]
    pub reservations: Reservations,
    #[serde(skip)]
    pub group_pictures: GroupPictureSources,
}

}

